import type { LucideProps } from 'lucide-react-native';
import { cssInterop } from 'nativewind';
import type { ComponentType } from 'react';

type LucideComponent = ComponentType<LucideProps>;

// Tracks which icons have been made className-aware (cssInterop mutates them).
const interopped = new WeakSet<LucideComponent>();

export interface IconProps extends LucideProps {
  /** A lucide icon component, e.g. `as={Home}`. */
  as: LucideComponent;
  className?: string;
}

/**
 * Renders a lucide icon that responds to Tailwind text-color classes.
 * Usage: `<Icon as={Home} className="text-muted-foreground" size={22} />`
 */
export function Icon({ as: IconComponent, size = 20, className, ...props }: IconProps) {
  if (!interopped.has(IconComponent)) {
    cssInterop(IconComponent, {
      className: { target: 'style', nativeStyleToProp: { color: true } },
    });
    interopped.add(IconComponent);
  }
  const Styled = IconComponent as ComponentType<LucideProps & { className?: string }>;
  return <Styled size={size} className={className} {...props} />;
}
